mapper.select:
select r.project_id projectId,p.project_name projectName,p.company_dept_id companyDeptId,p.base_currency currency,
 date_format(r.biz_date,'%Y-%m-%d') bizDate,r.result_id resultId,r.profit_amount profitAmount,r.is_adjustment isAdjustment,
 coalesce(s.tax_rate,t.tax_rate,0) taxRate,case when s.project_id is not null then '1' else '0' end taxFrozen,
 case when s.project_id is not null then s.configured when t.company_dept_id is not null then '1' else '0' end taxConfigured
from (
 select project_id,biz_date,result_id,profit_amount,0 is_adjustment from biz_project_daily_result where is_current='1'
 union all
 select project_id,posting_date,null,sum(profit_delta),1 from biz_closed_project_adjustment where status='APPROVED' group by project_id,posting_date
) r join biz_project p on p.project_id=r.project_id
left join biz_company_profit_tax t on t.company_dept_id=p.company_dept_id
left join biz_project_profit_tax_snapshot s on s.project_id=p.project_id
where p.del_flag='0'
and coalesce(p.sponsor_owner_user_id,p.initiator_user_id)=#{userId}
and p.project_id=#{projectId}
and p.company_dept_id=#{companyDeptId}
and r.biz_date<=#{dateTo}
order by r.project_id,r.biz_date,r.is_adjustment,r.result_id
